"""Build original Flyff equipment models for the MU inventory; generated by CodeRabbit.
Requires Python, NumPy and Pillow. Resource rights notices remain applicable.
"""
import json, pathlib, tempfile
import numpy as np
import convertir as c
from descargar import fetch, ENTRIES, REV

DEST=pathlib.Path(__file__).resolve().parents[2]/'public/flyff'
WEAPONS={
 'Espada del Dragón':'Item_WeaSwoFireis', 'Espada del Arcángel':'Item_WeaSwoAngel',
 'Bone Blade (Hoja Ósea)':'Item_WeaSwoBloody', 'Báculo Legendario':'Item_WeaStaWiz',
 'Báculo de Kundun':'Item_WeaStaAncient','Báculo de Platina':'Item_WeaStaCrystal',
 'Arco Celestial':'Item_WeaBowWoode','Ballesta de Cristal':'Item_WeaBowCrystal',
 'Arco Albatros':'Item_WeaBowAngel','Cetro del Señor Oscuro':'Item_WeaWanMisty',
 'Cetro Solemnidad':'Item_WeaWanDivine','Cetro Solemnidad Real':'Item_WeaWanAngel',
 'Espada Rúnica':'Item_WeaSwoCrystal','Espada Relámpago (Izq)':'Item_WeaSwoComet',
 'Espada Dancer Oscura':'Item_WeaSwoBlueSh','Espada Bastarda Rúnica':'Item_WeaSwoLegendG',
 'Escudo Dragón':'Item_ArmShiScale','Escudo Legendario':'Item_ArmShiStar',
 'Escudo de Hierro Oscuro':'Item_ArmShiTower',
}
SETS={'Dragon':'Mer01','Great Dragon':'Mer03','Legendary':'Mag01','Grand Soul':'Mag03',
      'Guardian':'Acr01','Divine':'Acr03','Dark Steel':'Ass01','Dark Master':'Ass03',
      'Hurricane':'Vag02','Volcano':'Mer02'}

def outfit(family,sex):
 g=c.GLB();data=c.chr_data(fetch(c.MODEL+'mvr_'+sex+'.chr'));bones=data['bones'];root=g.node(family+'_'+sex);joints=[]
 for b in bones:joints.append(g.node(b['name'],joints[b['parent']] if b['parent']>=0 else root,**c.trs(c.H@b['local']@c.H)))
 inv=np.array([(c.H@b['inv']@c.H).T.ravel() for b in bones]);g.doc['skins']=[dict(joints=joints,inverseBindMatrices=g.accessor(inv,kind='MAT4'),skeleton=joints[0])]
 for slot,part in [('torso','Upper'),('hands','Hand'),('feet','Foot'),('helmet','Cap')]:
  name=f'Part_{sex[0]}{family}{part}.o3d';obj=c.o3d(fetch(c.MODEL+name))
  for i,m in enumerate(obj['meshes']):
   parent=joints[m['parent']] if not m['skin'] and m['parentType']==2 else root
   g.mesh('equip_'+slot+'_'+str(i),m,parent,skin=0,extra={'source':name,'slot':slot})
 g.doc['extras']={'sourceRevision':REV,'sourceFamily':family,'sex':sex,'generatedBy':'CodeRabbit','rights':'Flyff reference resources; see licencias/'}
 path=f'equipo/{family}_{sex}.glb';g.save(DEST/path);return path

def main():
 result={'sourceRevision':REV,'weapons':{},'sets':{},'rights':'Original resource notices in licencias/'}
 with tempfile.TemporaryDirectory(prefix='flyff-equipment-') as scratch:
  c.OUT=pathlib.Path(scratch)
  for name,model in WEAPONS.items():
   path=f'equipo/{model.lower()}.glb'
   if not (DEST/path).exists():
    g=c.GLB();root=g.node(model)
    for i,m in enumerate(c.o3d(fetch(c.MODEL+model+'.o3d'))['meshes']):g.mesh('item_'+str(i),m,root)
    g.doc['extras']={'sourceRevision':REV,'source':model+'.o3d','generatedBy':'CodeRabbit','rights':'Flyff reference resources; see licencias/'};g.save(DEST/path)
   result['weapons'][name]=path;print(name,path,flush=True)
  built={}
  for name,family in SETS.items():
   result['sets'][name]={}
   for sex in ['male','female']:
    key=(family,sex)
    if key not in built:built[key]=outfit(family,sex)
    result['sets'][name][sex]=built[key]
   print(name,flush=True)
 (DEST/'equipo.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
 print('EQUIPMENT_READY',len(result['weapons']),len(built),flush=True)
if __name__=='__main__':main()
